# No Cayley graph of Z_13 with 2 generators has girth >=7. 
# Let's check girth values:
import networkx as nx

def cayley(gens, n):
    S = set()
    for g in gens:
        S.add(g%n); S.add((-g)%n)
    G = nx.Graph()
    G.add_nodes_from(range(n))
    for v in range(n):
        for g in S:
            u=(v+g)%n
            if u!=v: G.add_edge(v,u)
    return G

for a in range(1,7):
    for b in range(a+1,7):
        G = cayley([a,b], 13)
        try: g = nx.girth(G)
        except: g = 'inf'
        print(f"a={a},b={b}: girth={g}, E={G.number_of_edges()}")
